import React from 'react';
import { GatsbyImage, IGatsbyImageData } from 'gatsby-plugin-image';

interface OptimizedImageProps {
  /** Gatsby image data for responsive, optimized rendering */
  image?: IGatsbyImageData | null;
  /** Fallback image src (used when image data is not available) */
  src?: string;
  alt: string;
  className?: string;
  loading?: 'lazy' | 'eager';
}

const OptimizedImage: React.FC<OptimizedImageProps> = ({
  image,
  src,
  alt,
  className,
  loading = 'lazy',
}) => {
  if (image) {
    return (
      <GatsbyImage
        image={image}
        alt={alt}
        className={className}
        loading={loading}
      />
    );
  }

  // Fallback to plain img tag for non-processed images (e.g. remote URLs, videos)
  return (
    <img
      src={src}
      alt={alt}
      className={className}
      loading={loading}
    />
  );
};

export default OptimizedImage;